 .my-offer__seen {
   display: inline-flex;
   align-items: center;
   gap: 4px;
   padding: 2px 8px;
   border-radius: 999px;
   font-size: 11px;
   font-weight: 600;
   white-space: nowrap;
   border: 1px solid var(--border);
   color: var(--muted);
   background: rgba(0, 0, 0, 0.03);
 }
 .my-offer__seen--ack {
   color: #16a34a;
   background: rgba(22, 163, 74, 0.10);
   border-color: rgba(22, 163, 74, 0.35);
 }
 .my-offer__seen .seen-text-coarse { display: none; }
 .my-offer__seen .seen-text-precise { display: inline; }
 @media (max-width: 480px) {
   .my-offer__seen .seen-text-coarse { display: inline; }
   .my-offer__seen .seen-text-precise { display: none; }
 }
 .my-offer__verify {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   width: 18px;
   height: 18px;
   border-radius: 999px;
   font-size: 11px;
   font-weight: 700;
   cursor: help;
 }
 .my-offer__verify--ok {
   background: rgba(22, 163, 74, 0.15);
   color: #16a34a;
   border: 1px solid rgba(22, 163, 74, 0.4);
 }
 .my-offer__verify--unverified {
   background: rgba(0, 0, 0, 0.04);
   color: var(--muted);
   border: 1px solid var(--border);
 }
 .my-offers__note {
   font-size: 11px;
   color: var(--muted);
   padding: 6px 10px 8px;
   display: flex;
   align-items: center;
   flex-wrap: wrap;
   gap: 6px;
 }
 .my-offers__note .my-offer__verify { cursor: default; }
 .my-offer__upeg {
   background: none;
   border: 0;
   padding: 0;
   font: inherit;
   font-weight: 700;
   color: var(--text);
   cursor: pointer;
   display: inline-flex;
   align-items: center;
   gap: 8px;
 }
 /* Small uPEG art thumbnail prefixing the #id — same click target as the
    button, so tapping the art opens the modal too. Pixelated rendering
    keeps the 24x24 grid crisp at small sizes. */
 .my-offer__pfp {
   width: 28px;
   height: 28px;
   image-rendering: pixelated;
   border-radius: 2px;
   background: var(--bg);
   display: block;
   flex-shrink: 0;
 }
 .my-offer__id-label {
   text-decoration: underline;
   text-decoration-color: var(--border);
   text-underline-offset: 2px;
 }
 .my-offer__upeg:hover .my-offer__id-label { color: var(--accent); text-decoration-color: var(--accent); }
 .my-offer__upeg:hover { color: var(--accent); }
 .my-offer__price { font-weight: 700; font-variant-numeric: tabular-nums; }
 .my-offer__bidder { color: var(--text); text-decoration: none; }
 .my-offer__bidder:hover { color: var(--accent); }
 .my-offer__bidder--anon { color: var(--muted); font-style: italic; }
 .my-offer__from { color: var(--muted); font-size: 11px; }
 .my-offer__age, .my-offer__expires {
   color: var(--muted); font-size: 11px;
   font-variant-numeric: tabular-nums;
   white-space: nowrap;
 }
 .my-offer__cancel {
   width: 22px; height: 22px;
   padding: 0;
   border: 1.5px solid var(--border);
   background: var(--card);
   border-radius: 3px;
   color: var(--muted);
   cursor: pointer;
   font: inherit; font-size: 16px; line-height: 1;
   display: inline-flex; align-items: center; justify-content: center;
   transition: border-color 0.08s ease, color 0.08s ease, background 0.08s ease;
 }
 .my-offer__cancel:hover:not(:disabled) {
   border-color: crimson; color: crimson; background: rgba(220,38,38,0.05);
 }
 .my-offer__cancel:disabled { opacity: 0.5; cursor: wait; }

 /* Favorite heart */
 .match__fav, .modal__fav {
   background: none;
   border: 0;
   padding: 0 6px 0 0;
   cursor: pointer;
   display: inline-flex;
   align-items: center;
   color: #d1d5db;
   transition: color 0.1s ease, transform 0.08s ease;
 }
 .match__fav:hover, .modal__fav:hover { color: var(--accent); }
 .match__fav.on, .modal__fav.on { color: var(--accent); }

